import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = list(reader)

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 5
    header_index = 0

    # Skip leading preamble records when a later record has the expected width.
    if len(records[0]) != expected_width:
        for index, record in enumerate(records):
            if len(record) == expected_width and any(cell.strip() for cell in record):
                header_index = index
                break

    columns = list(records[header_index])
    if len(columns) < expected_width:
        columns.extend(f"Column {i + 1}" for i in range(len(columns), expected_width))

    rows = []
    for record in records[header_index + 1:]:
        if len(record) > len(columns):
            columns.extend(f"Column {i + 1}" for i in range(len(columns), len(record)))
        rows.append(list(record))

    for row in rows:
        row.extend([""] * (len(columns) - len(row)))

    return {"columns": columns, "rows": rows}
